```cpp
namespace slide::core::detail {
[[nodiscard]] constexpr bool take(std::string_view source, std::size_t &cursor, char token) noexcept
{
  if (cursor < source.size() && source[cursor] == token) { ++cursor; return true; }
  return false;
}
[[nodiscard]] constexpr bool consume(std::string_view source, std::size_t &cursor, std::string_view token) noexcept
{
  if (!source.substr(cursor).starts_with(token)) return false;
  cursor += token.size();
  return true;
}
} // namespace slide::core::detail
```

